import * as THREE from 'three/webgpu';
import { texture as textureNode } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture via cached loader
  const texture = ctx.textureLoader.load(config.imageUrl);

  // Calculate plane dimensions from atlas region aspect ratio (512 × 320 = 1.6:1)
  const aspectRatio = 512 / 320;
  const planeHeight = 1;
  const planeWidth = planeHeight * aspectRatio;

  // Create plane geometry for sprite
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Create material with texture using TSL
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: textureNode(texture),
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply transform from config
  if (config.scenePosition) {
    const { x = 0, y = 0, z = 0 } = config.scenePosition;
    mesh.position.set(x, y, z);
  }

  if (config.rotation) {
    const { x = 0, y = 0, z = 0 } = config.rotation;
    mesh.rotation.set(x, y, z);
  }

  if (config.scale) {
    const { x = 1, y = 1, z = 1 } = config.scale;
    mesh.scale.set(x, y, z);
  }

  group.add(mesh);

  // Setup cleanup
  group.userData.cleanup = function() {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  // Setup event handlers (empty for static card)
  group.userData.handlers = {};

  return group;
}
